# --- In-Memory Storage (Thread-Safe) ---

class Storage:
    def __init__(self):
        self._lock = threading.RLock()
        self.users: Dict[str, User] = {}
        self.projects: Dict[str, Project] = {}
        self.tasks: Dict[str, Task] = {}
        self.messages: Dict[str, Message] = {}
        self.feedback: Dict[str, Feedback] = {}
        self._task_completion_times: Dict[str, List[float]] = defaultdict(list)  # user_id -> list of durations (in hours)

    def add_user(self, user: User):
        with self._lock:
            self.users[user.user_id] = user

    def get_user(self, user_id: str) -> Optional[User]:
        with self._lock:
            return self.users.get(user_id)

    def add_project(self, project: Project):
        with self._lock:
            self.projects[project.project_id] = project

    def get_project(self, project_id: str) -> Optional[Project]:
        with self._lock:
            return self.projects.get(project_id)

    def add_task(self, task: Task):
        with self._lock:
            self.tasks[task.task_id] = task

    def update_task_status(self, task_id: str, new_status: str, completed_at: Optional[str] = None):
        with self._lock:
            if task_id in self.tasks:
                task = self.tasks[task_id]
                old_status = task.status
                task.status = new_status
                if new_status == "completed" and old_status != "completed":
                    task.completed_at = completed_at or datetime.now().isoformat()
                    # Record completion time
                    try:
                        start = datetime.fromisoformat(task.created_at)
                        end = datetime.fromisoformat(task.completed_at)
                        duration_hours = (end - start).total_seconds() / 3600
                        self._task_completion_times[task.assignee_id].append(duration_hours)
                    except Exception:
                        pass  # Ignore time calculation errors

    def add_message(self, message: Message):
        with self._lock:
            self.messages[message.message_id] = message

    def add_feedback(self, feedback: Feedback):
        with self._lock:
            self.feedback[feedback.feedback_id] = feedback

    def get_tasks_by_user(self, user_id: str) -> List[Task]:
        with self._lock:
            return [t for t in self.tasks.values() if t.assignee_id == user_id]

    def get_tasks_by_project(self, project_id: str) -> List[Task]:
        with self._lock:
            return [t for t in self.tasks.values() if t.project_id == project_id]

    def get_messages_by_project(self, project_id: str) -> List[Message]:
        with self._lock:
            return [m for m in self.messages.values() if m.project_id == project_id]

    def get_messages_by_task(self, task_id: str) -> List[Message]:
        with self._lock:
            return [m for m in self.messages.values() if m.task_id == task_id]

    def get_feedback_for_user(self, user_id: str) -> List[Feedback]:
        with self._lock:
            return [f for f in self.feedback.values() if f.reviewee_id == user_id]

    def get_completion_stats(self, user_id: str) -> Dict[str, Any]:
        with self._lock:
            tasks = self.get_tasks_by_user(user_id)
            completed = [t for t in tasks if t.status == "completed"]
            total = len(tasks)
            completed_count = len(completed)
            completion_rate = (completed_count / total * 100) if total > 0 else 0.0
            durations = self._task_completion_times.get(user_id, [])
            avg_time = sum(durations) / len(durations) if durations else 0.0
            return {
                "total_tasks": total,
                "completed_tasks": completed_count,
                "completion_rate": round(completion_rate, 2),
                "avg_completion_time_hours": round(avg_time, 2)
            }


